def svg(i=0):
    """El SVG de la figura `i`, negra y con su contraluz."""
    vb, d = FIGURAS[i % len(FIGURAS)]
    return ('<svg xmlns="http://www.w3.org/2000/svg" viewBox="' + vb + '">'
            '<defs><filter id="luz" x="-8%" y="-8%" width="116%" height="116%">'
            '<feMorphology in="SourceAlpha" operator="dilate" radius="5" result="d"/>'
            '<feGaussianBlur in="d" stdDeviation="8.75" result="b"/>'
            '<feFlood flood-color="#ffffff" flood-opacity=".28"/>'
            '<feComposite in2="b" operator="in" result="g"/>'
            '<feMerge><feMergeNode in="g"/><feMergeNode in="SourceGraphic"/></feMerge>'
            '</filter></defs>'
            '<path fill="#0a0a0d" fill-rule="evenodd" filter="url(#luz)" d="' + d + '"/></svg>')


def cual(quien=''):
    """Qué figura le toca a alguien: SIEMPRE la misma para el mismo nombre (sin tildes, banderas ni mayúsculas), así su
    carta no cambia de figura cada vez que se redibuja. Sin nombre, la de siempre."""
    import hashlib
    import unicodedata
    n = ''.join(ch for ch in unicodedata.normalize('NFKD', str(quien or '')).lower() if ch.isalnum())
    return int(hashlib.sha1(n.encode('utf-8')).hexdigest(), 16) % len(FIGURAS) if n else 0


def uri(quien=''):
    """La figura de alguien como imagen, para el `src` de un `<img>`. Base64 y no `utf8,`: va adentro de atributos con
    comillas simples y dobles (el `onerror` de la Temporada y la Competitiva), y en base64 no hay ninguna de las dos."""
    return 'data:image/svg+xml;base64,' + base64.b64encode(svg(cual(quien)).encode('utf-8')).decode('ascii')


SVG = svg(0)
#: la de siempre: lo que no sabe de quién es (y lo que la usaba antes de que hubiera cuatro)
URI = uri()


def img(clase='sil', quien=''):
    """El `<img>` de la silueta de `quien`, con su clase para el encuadre de cada carta."""
    return '<img class="%s" src="%s" alt="">' % (clase, uri(quien))


def onerror(clase='sil', quien=''):
    """El `onerror` de una foto que no carga: cae en la silueta de `quien`, una sola vez."""
    return "this.onerror=null;this.className='%s';this.src='%s'" % (clase, uri(quien))


def _self_check():
    import xml.etree.ElementTree as ET
    mal = 0

    def ok(c, que):
        nonlocal mal
        mal += not c
        print('   %s %s' % ('ok' if c else '🔴', que))
    print('\n  sin_foto.py — self-check\n')
    try:
        raiz = ET.fromstring(SVG)
        _x, _y, w, h = (float(v) for v in raiz.get('viewBox').split())
        ok(w == h, 'el SVG se lee y es cuadrado, como un avatar (%gx%g)' % (w, h))
    except ET.ParseError as e:
        ok(False, 'el SVG no se lee: %s' % e)
    ok("'" not in URI and '"' not in URI, 'la URI no trae comillas: entra en cualquier atributo')
    ok(len(URI) < 6000, 'pesa poco (%d caracteres): va adentro de cada carta' % len(URI))
    ok(URI in onerror() and 'this.onerror=null' in onerror(), 'el onerror cae una sola vez')
    # las cuatro: cuadradas, livianas, y a cada nombre le toca siempre la misma
    for i in range(len(FIGURAS)):
        try:
            _x, _y, w, h = (float(v) for v in ET.fromstring(svg(i)).get('viewBox').split())
            ok(w == h and len(uri()) < 8000, 'la figura %d se lee y es cuadrada' % (i + 1))
        except ET.ParseError as e:
            ok(False, 'la figura %d no se lee: %s' % (i + 1, e))
    reparto = [cual(n) for n in ('Konan', 'Snow', 'Oasis', 'Catarsis', 'Makmah', 'Cronox', 'Erian', 'Abyssus')]
    ok(len(set(reparto)) >= 3 and cual('Snow 🇨🇴') == cual('snow') and cual('') == 0,
       'el nombre elige siempre la misma figura, y se reparten (%s)' % reparto)
    out = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'salida')
    try:
        os.makedirs(out, exist_ok=True)
        with open(os.path.join(out, 'sin_foto.svg'), 'w', encoding='utf-8') as f:
            f.write(SVG)
    except OSError:
        pass
    print('\n  %s\n' % ('todo ok' if not mal else '🔴 %d mal' % mal))
    return 1 if mal else 0


if __name__ == '__main__':
    raise SystemExit(_self_check())
